// Traditional Function
function greet(name) {
  return 'Hello ' + name;
}

// Arrow Function (Long form)
const greetArrow = (name) => {
  return `Hello ${name}`;
};

// Arrow Function (Short form with implicit return)
const greetShort = name => `Hello ${name}`;

const user = {
  id: 1,
  username: 'dev_learner',
  email: 'learn@example.com'
};

// Instead of: const username = user.username;
// Use destructuring:
const { username, email } = user;

console.log(username); // 'dev_learner'

// Updating an object without changing the original
const settings = { theme: 'dark', notifications: true };

// Create a new object, copy everything from settings, but change theme
const newSettings = { ...settings, theme: 'light' };

console.log(settings.theme);    // 'dark' (original stays same)
console.log(newSettings.theme); // 'light' (new copy is updated)

